import { BadRequestException, Logger } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { fromTemporaryCredentials } from '@aws-sdk/credential-providers';
import { AwsCredentialIdentity } from '@aws-sdk/types';
import { getInstanceWithFilters } from '../../utils/aws/awsEc2.js';

/**
 * The shape of the cloudIAM block sent in on a settings update.
 * Declared locally (instead of importing the DTO) to avoid a circular import with update-settings.dto.
 */
export interface CloudIAMInput {
    iamRoleArn?: string;
    externalId?: string;
}

export const CLOUD_IAM_MISSING_ROLE_MESSAGE =
    'cloudIAM: An iamRoleArn must be supplied. Send an empty iamRoleArn ("") to disconnect the IAM role';

export const CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE =
    'Unable to assume the IAM role provided with the external ID supplied. Please double check the role, its trust policy and the external ID';

export const CLOUD_IAM_INVENTORY_FAILURE_MESSAGE =
    'The IAM role provided was assumed but it cannot read the EC2 instance inventory MeteringCo collects from. Please double check the IAM permissions attached to the role (ec2:DescribeInstances)';

/**
 * The region used when proving the customer supplied role can be assumed and used.
 */
export const cloudIAMValidationRegion = () => process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

const logger = new Logger('CloudIAMAuthorizer');

/**
 * A cloudIAM block with a blank role means the customer wants to disconnect MeteringCo from their account.
 */
export const isCloudIAMDisconnect = (cloudIAM: CloudIAMInput): boolean =>
    !!cloudIAM && typeof cloudIAM.iamRoleArn === 'string' && cloudIAM.iamRoleArn.trim() === '';

/**
 * A cloudIAM block that does not name a role at all is invalid, it is not a disconnect request.
 */
export const cloudIAMNamesNoRole = (cloudIAM: CloudIAMInput): boolean =>
    !cloudIAM || typeof cloudIAM.iamRoleArn !== 'string';

/**
 * Assume the customer supplied role with the customer supplied external id.
 * Returns the temporary credentials the role handed back.
 */
export const assumeScraperRole = async ({
    iamRoleArn,
    externalId,
}: CloudIAMInput): Promise<AwsCredentialIdentity | undefined> => {
    const credentialProvider = fromTemporaryCredentials({
        params: {
            RoleArn: iamRoleArn,
            ExternalId: externalId ? externalId : undefined,
            RoleSessionName: 'meteringco-settings-validation',
        },
        clientConfig: { region: cloudIAMValidationRegion() },
    });
    return credentialProvider();
};

/**
 * Prove the supplied scraper role can be assumed with the supplied external id and that the credentials
 * handed back can read the instance inventory collection relies on.
 *
 * Throws a BadRequestException if either check fails so that nothing else in the save is written.
 */
export const validateScraperRole = async (cloudIAM: CloudIAMInput): Promise<void> => {
    if (cloudIAMNamesNoRole(cloudIAM)) {
        throw new BadRequestException([CLOUD_IAM_MISSING_ROLE_MESSAGE]);
    }
    let credentials: AwsCredentialIdentity;
    try {
        credentials = await assumeScraperRole(cloudIAM);
    } catch (e) {
        logger.error(`Failed to assume customer supplied role ${cloudIAM?.iamRoleArn}: ${e?.message ?? e}`);
        throw new BadRequestException([CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE]);
    }
    if (!credentials?.accessKeyId) {
        logger.error(`No credentials returned when assuming customer supplied role ${cloudIAM?.iamRoleArn}`);
        throw new BadRequestException([CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE]);
    }
    try {
        // The very same read collection performs against a customers account.
        await getInstanceWithFilters(cloudIAMValidationRegion(), credentials, []);
    } catch (e) {
        logger.error(
            `Assumed role ${cloudIAM?.iamRoleArn} cannot read the instance inventory: ${e?.message ?? e}`,
        );
        throw new BadRequestException([CLOUD_IAM_INVENTORY_FAILURE_MESSAGE]);
    }
};

/**
 * Validates a cloudIAM block and returns what should be persisted.
 * A blank role is a disconnect, which also clears the external id.
 */
export const resolveCloudIAMForSave = async (cloudIAM: CloudIAMInput): Promise<CloudIAMInput> => {
    if (isCloudIAMDisconnect(cloudIAM)) {
        // Disconnect, the external id is meaningless without a role so it is cleared.
        return { iamRoleArn: '', externalId: '' };
    }
    await validateScraperRole(cloudIAM);
    return { iamRoleArn: cloudIAM.iamRoleArn, externalId: cloudIAM.externalId ? cloudIAM.externalId : '' };
};

@ValidatorConstraint({ name: 'UsableCloudIAMRoleRule', async: true })
export class UsableCloudIAMRoleRule implements ValidatorConstraintInterface {
    private message = CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE;

    async validate(cloudIAM: CloudIAMInput) {
        if (cloudIAM === undefined || cloudIAM === null) {
            // Nothing supplied, nothing to check.
            return true;
        }
        if (isCloudIAMDisconnect(cloudIAM)) {
            return true;
        }
        try {
            await validateScraperRole(cloudIAM);
            return true;
        } catch (e) {
            const [message] = [].concat(e?.getResponse?.()?.message ?? e?.message ?? []);
            this.message = message || CLOUD_IAM_ASSUME_ROLE_FAILURE_MESSAGE;
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        return this.message;
    }
}

export function UsableCloudIAMRole(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'UsableCloudIAMRole',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [],
            options: validationOptions,
            validator: UsableCloudIAMRoleRule,
        });
    };
}
