        expect(res.body.message[0]).toEqual(expect.stringContaining('IAM'));
        expect(mockInfluxService.loadPoints).not.toBeCalled();
    });

    test('rejects a role which cannot read the instance inventory', async () => {
        const res = await request(server).put('/settings').send({ cloudIAM: { iamRoleArn: noPermRole, externalId } });
        console.log('NO PERM', res.status, JSON.stringify(res.body).slice(0, 400));
        expect(res.status).toBe(400);
        expect(res.body.message[0]).toEqual(expect.stringContaining('IAM'));
        expect(mockInfluxService.loadPoints).not.toBeCalled();
    });

    test('rejects a role which does not exist', async () => {
        const res = await request(server)
            .put('/settings')
            .send({ cloudIAM: { iamRoleArn: 'wow a fake role', externalId: 'foobar' } });
        console.log('FAKE ROLE', res.status, JSON.stringify(res.body).slice(0, 400));
        expect(res.status).toBe(400);
        expect(res.body.message[0]).toEqual(expect.stringContaining('IAM'));
        expect(mockInfluxService.loadPoints).not.toBeCalled();
    });

    test('a cloudIAM block with no role is invalid', async () => {
        const res = await request(server).put('/settings').send({ cloudIAM: { externalId: 'foobar' } });
        console.log('NO ROLE', res.status, JSON.stringify(res.body).slice(0, 400));
        expect(res.status).toBe(400);
        expect(mockInfluxService.loadPoints).not.toBeCalled();
    });

    test('a blank role disconnects and clears the external id', async () => {
