import { SettingsService } from './settings.service.js';
import { ValidationPipe } from '@nestjs/common';
import { UpdateSettingsDto } from './dto/update-settings.dto.js';
import { IAMClient, CreateRoleCommand, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import { STSClient, GetCallerIdentityCommand } from '@aws-sdk/client-sts';

const iam = new IAMClient({});
const readOnly = { Version: '2012-10-17', Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }] };
const createRole = async (name, principal, externalId, policy) => {
    const trust = {
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: principal },
                Action: 'sts:AssumeRole',
                ...(externalId ? { Condition: { StringEquals: { 'sts:ExternalId': externalId } } } : {}),
            },
        ],
    };
    let arn;
    try {
        arn = (await iam.send(new CreateRoleCommand({ RoleName: name, AssumeRolePolicyDocument: JSON.stringify(trust) }))).Role.Arn;
    } catch (e) {
        arn = `arn:aws:iam::${principal.split(':')[4]}:role/${name}`;
    }
    await iam.send(new PutRolePolicyCommand({ RoleName: name, PolicyName: 'p', PolicyDocument: JSON.stringify(policy) }));
    return arn;
};

describe('validation pipe', () => {
    const pipe = new ValidationPipe({ whitelist: true, transform: true });
    const meta = { type: 'body' as const, metatype: UpdateSettingsDto };
    let goodRole;
    beforeAll(async () => {
        console.log(!!SettingsService);
        const { Arn } = await new STSClient({}).send(new GetCallerIdentityCommand({}));
        goodRole = await createRole('pipe-good-role', Arn, 'pipe-ext', readOnly);
    });
    it('lets a good role through untouched', async () => {
        const out = await pipe.transform({ cloudIAM: { iamRoleArn: goodRole, externalId: 'pipe-ext' } }, meta);
        console.log('GOOD', JSON.stringify(out));
        expect(out.cloudIAM.iamRoleArn).toEqual(goodRole);
        expect(out.cloudIAM.externalId).toEqual('pipe-ext');
    });
    it('400s on wrong external id', async () => {
        await expect(pipe.transform({ cloudIAM: { iamRoleArn: goodRole, externalId: 'bad' } }, meta)).rejects.toMatchObject({ status: 400 });
        const err = await pipe.transform({ cloudIAM: { iamRoleArn: goodRole, externalId: 'bad' } }, meta).catch((e) => e);
        console.log('BAD', JSON.stringify(err.getResponse()));
        expect(err.getResponse().message[0]).toEqual(expect.stringContaining('IAM'));
    });
    it('400s when no role is named', async () => {
        const err = await pipe.transform({ cloudIAM: { externalId: 'bad' } }, meta).catch((e) => e);
        console.log('NOROLE', JSON.stringify(err.getResponse()));
        expect(err.status).toBe(400);
    });
    it('allows a disconnect', async () => {
