import { Test, TestingModule } from '@nestjs/testing';
import { SettingsService } from './settings.service.js';
import { createMock } from '@golevelup/ts-jest';
import { InfluxService } from '../influx/influx.service.js';
import { CreateRoleCommand, IAMClient, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import { GetCallerIdentityCommand, STSClient } from '@aws-sdk/client-sts';

const iam = new IAMClient({});
const instanceReadPolicy = {
    Version: '2012-10-17',
    Statement: [{ Effect: 'Allow', Action: ['ec2:DescribeInstances'], Resource: '*' }],
};
const noInstanceReadPolicy = {
    Version: '2012-10-17',
    Statement: [{ Effect: 'Allow', Action: ['s3:ListBucket'], Resource: '*' }],
};

const createRole = async (
    name: string,
    principal: string,
    externalId: string | undefined,
    policy: Record<string, unknown>,
) => {
    const trustPolicy = {
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: principal },
                Action: 'sts:AssumeRole',
                ...(externalId ? { Condition: { StringEquals: { 'sts:ExternalId': externalId } } } : {}),
            },
        ],
    };
    let arn = `arn:aws:iam::${principal.split(':')[4]}:role/${name}`;
    try {
        const { Role } = await iam.send(
            new CreateRoleCommand({ RoleName: name, AssumeRolePolicyDocument: JSON.stringify(trustPolicy) }),
        );
        arn = Role.Arn;
    } catch (e) {
        // The role already exists from a prior run of this suite.
    }
    await iam.send(
        new PutRolePolicyCommand({ RoleName: name, PolicyName: 'policy', PolicyDocument: JSON.stringify(policy) }),
    );
    return arn;
};

describe('cloudIAM scraper role validation', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    let assumableRole: string;
    let roleWithoutInstanceAccess: string;
    const externalId = 'settings-validation-external-id';
    const businessID = 'some-business-id';

    beforeAll(async () => {
        const { Arn } = await new STSClient({}).send(new GetCallerIdentityCommand({}));
        assumableRole = await createRole('settings-spec-scraper-role', Arn, externalId, instanceReadPolicy);
        roleWithoutInstanceAccess = await createRole('settings-spec-no-access-role', Arn, externalId, noInstanceReadPolicy);
    });

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('saves a role which can be assumed with the external id supplied and can read the instance inventory', async () => {
        const { data } = await service.update({ businessID, cloudIAM: { iamRoleArn: assumableRole, externalId } });
        expect(influxService.loadPoints).toBeCalledTimes(1);
        expect(data[0].cloudIAM).toEqual({ iamRoleArn: assumableRole, externalId });
    });

    it('rejects the save, writing nothing, when the role cannot be assumed with the external id supplied', async () => {
        await expect(
            service.update({
                businessID,
                businessName: 'This should never be written',
                cloudIAM: { iamRoleArn: assumableRole, externalId: 'not-the-right-external-id' },
            }),
        ).rejects.toMatchObject({ status: 400 });
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('rejects the save, writing nothing, when the assumed credentials cannot read the instance inventory', async () => {
        await expect(
            service.update({ businessID, cloudIAM: { iamRoleArn: roleWithoutInstanceAccess, externalId } }),
        ).rejects.toMatchObject({ status: 400 });
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('rejects a cloudIAM block which does not name a role instead of treating it as a disconnect', async () => {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore the api allows this shape to be sent in
        await expect(service.update({ businessID, cloudIAM: { externalId } })).rejects.toMatchObject({ status: 400 });
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('treats a blank role as a disconnect and clears the external id', async () => {
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([
            { businessID, cloudIAM: JSON.stringify({ iamRoleArn: assumableRole, externalId }) } as never,
        ]);
        const { data } = await service.update({ businessID, cloudIAM: { iamRoleArn: '', externalId } });
        expect(influxService.loadPoints).toBeCalledTimes(1);
        expect(data[0].cloudIAM).toEqual({ iamRoleArn: '', externalId: '' });
    });

    it('does not touch the stored cloudIAM when a save does not include it', async () => {
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([
            { businessID, cloudIAM: JSON.stringify({ iamRoleArn: assumableRole, externalId }) } as never,
        ]);
        const { data } = await service.update({ businessID, logoUrl: 'https://example.com/logo.png' });
        expect(influxService.loadPoints).toBeCalledTimes(1);
        expect(data[0].cloudIAM).toEqual({ iamRoleArn: assumableRole, externalId });
    });
});
EOF
